import{_ as a,o as e,a as i,b as l}from"./app.C41L12d5.js";const n="/ascendc.github.io/assets/gemv_m1.DLIlrNu4.png",o="/ascendc.github.io/assets/non_gemv_m1.DJ3IVVnt.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矩阵编程（高阶API）","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/matrix_advanced_api"},{"text":"特性场景","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matmul_features"},{"text":"矩阵向量乘","link":"/guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matrix_vector_multiply"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matrix_vector_multiply.md","filePath":"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matrix_vector_multiply.md","outlineHeaders":[{"level":2,"title":"功能介绍","slug":"功能介绍","link":"#功能介绍"},{"level":2,"title":"使用场景","slug":"使用场景","link":"#使用场景"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787050286000}'),p={name:"guide/operator_practice/simd_operator_impl/matrix_advanced_api/feature_scenarios/matrix_vector_multiply.md"};function r(_,t,s,c,m,d){return e(),i("div",null,[...t[0]||(t[0]=[l('<div><article class="markdown-body"><h1>矩阵向量乘<span id="ZH-CN_TOPIC_0000002500548098"></span></h1><h2 id="功能介绍">功能介绍<span id="zh-cn_topic_0000002264077892_section310824820358"></span><a class="header-anchor" href="#功能介绍">​</a></h2><p>矩阵向量乘（General Matrix-Vector multiplication），即GEMV，是指Matmul计算中M=1，形状为(1, K)的左矩阵A与形状为(K, N)的右矩阵B进行矩阵乘运算的场景。Matmul支持在Tiling侧与核函数（Kernel）侧通过配置A矩阵的数据格式为<a href="../../../../technical_appendix/concepts_and_terms/neural_networks_and_operators/data_layout.html#li51557161818">VECTOR</a>来开启GEMV模式，从而高效处理M=1的计算场景。若在M=1时未开启GEMV模式，Matmul计算则将M方向作为非对齐场景进行处理。GEMV模式相较于非对齐处理方式，搬运数据量更少，性能更好。</p><p>以M=1，K=256，N=32，左右矩阵数据类型为half的Matmul为具体示例，说明GEMV模式的Matmul API内部处理过程。</p><ul><li><p>GEMV模式</p><p>将A矩阵从L1 Buffer（A1）搬运到L0A Buffer（A2）时，1*256的向量被当作16*16的矩阵进行处理，调用<a href="../../../../../api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load.html">LoadData</a>接口一次完成16*16分形大小的矩阵搬运。B矩阵的搬运以及矩阵乘计算跟基础场景相同，如下图所示。</p><p><strong>图1</strong> GEMV模式M=1的矩阵乘计算示意图<span id="zh-cn_topic_0000002264077892_fig18149171416184"></span><br><img src="'+n+'" alt title="GEMV模式M-1的矩阵乘计算示意图"></p></li><li><p>非GEMV模式</p><p>将A矩阵从L1 Buffer（A1）搬运到L0A Buffer（A2）时，1*256的向量被当作非对齐矩阵数据进行处理，将M方向对齐到32字节后进行搬运。调用<a href="../../../../../api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load.html">LoadData</a>接口每次搬运16*16分形大小的矩阵，一共搬运K/16=16次，导致搬运数据量增加，性能相较于GEMV模式差，如下图所示。</p><p><strong>图2</strong> 非GEMV模式M=1的矩阵乘计算示意图<span id="zh-cn_topic_0000002264077892_fig15267820101910"></span><br><img src="'+o+`" alt title="非GEMV模式M-1的矩阵乘计算示意图"></p></li></ul><h2 id="使用场景">使用场景<span id="zh-cn_topic_0000002264077892_section118051016163613"></span><a class="header-anchor" href="#使用场景">​</a></h2><p>形状为(1, K)的A矩阵（M=1，K&gt;1）做矩阵乘计算，即输入A矩阵的数据是向量数据。</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000002264077892_section14160134220363"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>在Matmul计算中，若要开启GEMV模式，A矩阵的原始输入形状M必须等于1。</p></li><li><p>GEMV场景下，左矩阵A不支持转置。</p></li><li><p>GEMV场景下，Global Memory上的左矩阵数据需要保证16字节对齐。</p></li><li><p><a href="mx_matmul_scenario.html">MxMatmul场景</a>计算矩阵向量乘时，左矩阵A和左量化系数矩阵scaleA仅支持内存逻辑位置为TPosition::GM。</p></li></ul><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000002264077892_section15486294368"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>完整的算子样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/00_matmul/matmul_format_gemv">matmul_gemv算子样例</a>。</p><ul><li><p>Tiling实现</p><p>调用SetAType接口，设置A矩阵的数据格式为CubeFormat::VECTOR，其它Tiling实现与<a href="../operator_impl.html">基础场景</a>相同。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());
matmul_tiling::MatmulApiTiling tiling(ascendcPlatform);
// 调用设置A矩阵的格式为CubeFormat::VECTOR
tiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::VECTOR, matmul_tiling::DataType::DT_FLOAT16);
tiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16); 
tiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
tiling.SetBiasType(AscendC::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT); 
... // 其他实现内容
optiling::TCubeTiling tilingData;   
int ret = tiling.GetTiling(tilingData);
</code></pre></div></li><li><p>核函数（Kernel）实现</p><p>相较于<a href="../operator_impl.html#zh-cn_topic_0000001622514006_li1032116474330">基础场景</a>，GEMV场景在创建Matmul对象时，设置模板参数A_TYPE的数据格式为CubeFormat::VECTOR。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>#include &quot;lib/matmul_intf.h&quot;

using A_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::VECTOR, half&gt;; 
using B_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt;;
using C_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt;; 
using BIAS_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt;; 
AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE&gt; mm;
</code></pre></div></li></ul></article></div>`,1)])])}const g=a(p,[["render",r]]);export{h as __pageData,g as default};
